// Generated by EduBoard IDE. Blocks are the source of truth.
#include <Adafruit_SH110X.h>
#include <Arduino.h>
#include <Wire.h>
#include <math.h>

Adafruit_SH1106G eduDisplay(128, 64, &Wire, -1);
bool eduDisplayReady = false;

void setup() {
  Serial.begin(115200);
  Wire.begin(21, 22);
  eduDisplayReady = eduDisplay.begin(0x3C, true);
  if (!eduDisplayReady) Serial.println("SH1106 not found");
  if (eduDisplayReady) {
    eduDisplay.clearDisplay();
    eduDisplay.setTextSize(1);
    eduDisplay.setTextColor(SH110X_WHITE);
    eduDisplay.setCursor(0, 0);
    eduDisplay.println("Hello, EduBoard!");
    eduDisplay.display();
  }
}

void loop() {
  delay(1000);
}
